<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Concerns\HasUuids;
use Illuminate\Database\Eloquent\Model;
class PurchaseReturn extends Model { use HasUuids; protected $table = 'purchase_returns'; protected $fillable = ['tenant_id','company_id','branch_id','purchase_order_id','goods_receipt_id','created_by','number','state','idempotency_key','return_date','reason','reason_detail','priority','requested_resolution','internal_reference','notes','approval_status','shipment_status','supplier_resolution_status','approved_by','approved_at','dispatched_by','dispatched_at']; protected function casts(): array { return ['return_date'=>'date','approved_at'=>'datetime','dispatched_at'=>'datetime']; } public function items(){return $this->hasMany(PurchaseReturnItem::class);} public function supplier(){return $this->hasOneThrough(Supplier::class,PurchaseOrder::class,'id','id','purchase_order_id','supplier_id');} public function purchaseOrder(){return $this->belongsTo(PurchaseOrder::class);} public function goodsReceipt(){return $this->belongsTo(GoodsReceipt::class);} public function company(){return $this->belongsTo(Company::class);} public function branch(){return $this->belongsTo(Branch::class);} public function shipment(){return $this->hasOne(PurchaseReturnShipment::class);} }
